 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    # Rows made entirely of the frame color delimit each motif panel.
    # The hollow left motif is matched to the corresponding right silhouette,
    # allowing rotations and reflections, then colored with that object's color.
    panel_width = next((c for c, value in enumerate(grid[0]) if value != frame), w)
    dividers = [r for r in range(h) if all(v == frame for v in grid[r][:panel_width])]
    groups = [(dividers[i] + 1, dividers[i + 1]) for i in range(len(dividers) - 1)]

    def normalize(points):
        r0 = min(r for r, c in points)
        c0 = min(c for r, c in points)
        return frozenset((r - r0, c - c0) for r, c in points)

    def orientations(shape):
        result = set()
        for flip in (1, -1):
            for turns in range(4):
                points = [(r, c * flip) for r, c in shape]
                for _ in range(turns):
                    points = [(c, -r) for r, c in points]
                result.add(normalize(points))
        return result

    objects = []
    for start, end in groups:
        points = [(r, c - panel_width - 1)
                  for r in range(start, end)
                  for c in range(panel_width + 1, w)
                  if grid[r][c] != 0]
        if points:
            color = grid[points[0][0]][points[0][1] + panel_width + 1]
            objects.append((normalize(points), color))

    output = [row[:panel_width] for row in grid]
    for start, end in groups:
        holes = [(r - start, c - 1)
                 for r in range(start, end)
                 for c in range(1, panel_width - 1)
                 if grid[r][c] == 0]
        if not holes:
            continue
        hole_shape = normalize(holes)
        color = next(color for shape, color in objects
                     if hole_shape in orientations(shape))
        for r in range(start, end):
            for c in range(1, panel_width - 1):
                if grid[r][c] == 0:
                    output[r][c] = color
    return output
"
